//! Gate V2-Golden test suite for `WP-7.2b` (EA RefPack / BTree / Huffman codecs).
//!
//! Oracle: `docs/golden_vectors/WP7_2b_Compression.json`, generated by
//! `tests/cpp_harness/gen_wave4_compression.cpp` from the unmodified vendor EAC sources:
//! 1,000 small vectors with full hex blobs (seeds 0..999) and 12 large vectors (seeds
//! 1000..1011) recorded as FNV-1a 64 digests, whose payloads are regenerated here.
//!
//! When implementing `WP-7.2b`, remove the four `#[ignore]` attributes below so these suites
//! run in `cargo test --workspace` and CI. `test_wp7_2b_payload_generator_matches_cpp` is not
//! ignored: it checks this file's port of the C++ payload generator and needs no codec code.

use zh_common::golden_json::{decode_hex_bytes, extract_vector_lines, get_str, get_u32};
use zh_common::io::compression::{
    btree, compress_data, decompress_data, get_compression_type, get_uncompressed_size, huff,
    is_data_compressed, refpack, CodecError, CompressionType, COMPRESSION_HEADER_LEN,
};

const WP7_2B_JSON: &str = include_str!("../../../docs/golden_vectors/WP7_2b_Compression.json");
const SMALL_COUNT: usize = 1000;
const LARGE_COUNT: usize = 12;
const EDGE_LENS: [u32; 19] = [
    0, 1, 2, 3, 4, 5, 7, 8, 9, 15, 16, 17, 31, 32, 64, 128, 256, 384, 512,
];

struct Codec {
    name: &'static str,
    comp_type: CompressionType,
    magic: &'static [u8; 4],
    hex_key: &'static str,
    len_key: &'static str,
    fnv_key: &'static str,
    encode: fn(&[u8]) -> Vec<u8>,
    decode: fn(&[u8]) -> Result<Vec<u8>, CodecError>,
    is: fn(&[u8]) -> bool,
    size: fn(&[u8]) -> i32,
}

const CODECS: [Codec; 3] = [
    Codec {
        name: "refpack",
        comp_type: CompressionType::RefPack,
        magic: b"EAR\0",
        hex_key: "ref_hex",
        len_key: "ref_len",
        fnv_key: "ref_fnv",
        encode: refpack::encode,
        decode: refpack::decode,
        is: refpack::is,
        size: refpack::size,
    },
    Codec {
        name: "btree",
        comp_type: CompressionType::BTree,
        magic: b"EAB\0",
        hex_key: "btree_hex",
        len_key: "btree_len",
        fnv_key: "btree_fnv",
        encode: btree::encode,
        decode: btree::decode,
        is: btree::is,
        size: btree::size,
    },
    Codec {
        name: "huff",
        comp_type: CompressionType::Huff,
        magic: b"EAH\0",
        hex_key: "huff_hex",
        len_key: "huff_len",
        fnv_key: "huff_fnv",
        encode: huff::encode,
        decode: huff::decode,
        is: huff::is,
        size: huff::size,
    },
];

/// Port of `splitmix32` in the C++ harness.
fn splitmix32(s: &mut u32) -> u32 {
    *s = s.wrapping_add(0x9e37_79b9);
    let mut z = *s;
    z = (z ^ (z >> 16)).wrapping_mul(0x85eb_ca6b);
    z = (z ^ (z >> 13)).wrapping_mul(0xc2b2_ae35);
    z ^ (z >> 16)
}

fn fnv1a64(buf: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for &b in buf {
        h ^= u64::from(b);
        h = h.wrapping_mul(0x0000_0100_0000_01b3);
    }
    h
}

fn seed_rng(seed: u32) -> u32 {
    seed.wrapping_mul(0x9e37_79b9).wrapping_add(0x517c_c1b7)
}

/// Port of `make_payload` in the C++ harness, including exactly when `rng` advances.
fn make_payload(seed: u32, len: u32, pattern: u32, period: u32, rng: &mut u32) -> Vec<u8> {
    let mut out = vec![0u8; len as usize];
    match pattern {
        0 => {
            let mut b = (splitmix32(rng) & 0xff) as u8;
            for i in 0..len {
                if (i & 31) == 0 {
                    b = (splitmix32(rng) & 0xff) as u8;
                }
                out[i as usize] = b;
            }
        }
        1 => {
            const SAMPLE: &[u8] =
                b"Object AmericaTankCrusader\n  BuildCost = 900\n  BuildTime = 10.0\nEnd\n";
            for i in 0..len {
                out[i as usize] = SAMPLE[(i.wrapping_add(seed) % SAMPLE.len() as u32) as usize];
            }
        }
        2 => {
            for i in 0..len {
                out[i as usize] = if (i & 3) == 0 {
                    (i >> 2) as u8
                } else {
                    ((seed >> (i & 3)) & 0xff) as u8
                };
            }
        }
        3 => {
            for i in 0..len {
                out[i as usize] = if i % 7 < 4 {
                    ((i / 7) & 0xff) as u8
                } else {
                    (splitmix32(rng) & 0xff) as u8
                };
            }
        }
        4 => {
            for i in 0..len {
                out[i as usize] = (splitmix32(rng) & 0xff) as u8;
            }
        }
        _ => {
            for i in 0..len {
                out[i as usize] = if i >= period && ((i >> 10) % 3) != 0 {
                    out[(i - period) as usize]
                } else {
                    (splitmix32(rng) & 0xff) as u8
                };
            }
        }
    }
    out
}

fn small_payload(seed: u32) -> Vec<u8> {
    let mut rng = seed_rng(seed);
    let edge_count = EDGE_LENS.len() as u32;
    let len = if seed < 2 * edge_count {
        EDGE_LENS[(seed % edge_count) as usize]
    } else {
        splitmix32(&mut rng) % 257
    };
    make_payload(seed, len, seed % 5, 0, &mut rng)
}

fn large_payload(line: &str) -> (u32, Vec<u8>) {
    let seed = get_u32(line, "seed").expect("seed");
    let len = get_u32(line, "len").expect("len");
    let pattern = get_u32(line, "pattern").expect("pattern");
    let period = get_u32(line, "period").expect("period");
    let mut rng = seed_rng(seed);
    (seed, make_payload(seed, len, pattern, period, &mut rng))
}

fn hex_field(line: &str, key: &str) -> Vec<u8> {
    decode_hex_bytes(get_str(line, key).expect(key)).expect(key)
}

fn fnv_field(line: &str, key: &str) -> u64 {
    u64::from_str_radix(get_str(line, key).expect(key), 16).expect(key)
}

fn vector_lines() -> Vec<&'static str> {
    let lines = extract_vector_lines(WP7_2B_JSON);
    assert_eq!(lines.len(), SMALL_COUNT + LARGE_COUNT, "vector count");
    lines
}

#[test]
fn test_wp7_2b_payload_generator_matches_cpp() {
    let lines = vector_lines();
    for (i, line) in lines[..SMALL_COUNT].iter().enumerate() {
        let seed = get_u32(line, "seed").expect("seed");
        assert_eq!(seed as usize, i, "small vectors are in seed order");
        assert_eq!(
            small_payload(seed),
            hex_field(line, "src_hex"),
            "seed {seed} payload"
        );
    }
    for line in &lines[SMALL_COUNT..] {
        let (seed, src) = large_payload(line);
        assert_eq!(
            src.len() as u32,
            get_u32(line, "len").expect("len"),
            "seed {seed} len"
        );
        assert_eq!(
            fnv1a64(&src),
            fnv_field(line, "src_fnv"),
            "seed {seed} payload digest"
        );
    }
}

#[test]
#[ignore = "WP-7.2b: remove when the codecs are implemented"]
fn test_wp7_2b_compression_1000_small_golden_vectors() {
    let lines = vector_lines();
    for line in &lines[..SMALL_COUNT] {
        let seed = get_u32(line, "seed").expect("seed");
        let src = hex_field(line, "src_hex");
        for c in &CODECS {
            let ctx = format!("seed {seed} {}", c.name);
            let blob = hex_field(line, c.hex_key);
            if blob.is_empty() {
                // compressData returned 0 in C++.
                assert_eq!(
                    compress_data(c.comp_type, &src),
                    None,
                    "{ctx}: compress_data"
                );
                continue;
            }
            let stream = &blob[COMPRESSION_HEADER_LEN..];
            assert_eq!(&blob[..4], c.magic, "{ctx}: oracle magic");

            assert_eq!((c.encode)(&src), stream, "{ctx}: encode");
            assert_eq!(
                compress_data(c.comp_type, &src).as_deref(),
                Some(&blob[..]),
                "{ctx}: compress_data"
            );
            assert_eq!(
                get_compression_type(&blob),
                c.comp_type,
                "{ctx}: get_compression_type"
            );
            assert!(is_data_compressed(&blob), "{ctx}: is_data_compressed");
            assert_eq!(
                get_uncompressed_size(&blob),
                src.len() as i32,
                "{ctx}: get_uncompressed_size"
            );
            assert!((c.is)(stream), "{ctx}: is");
            assert_eq!((c.size)(stream), src.len() as i32, "{ctx}: size");

            if c.comp_type == CompressionType::Huff && src.is_empty() {
                // HUFF_decode never terminates on the stream HUFF_encode makes for empty
                // input, so there is no reference result. The port only has to return.
                let _ = (c.decode)(stream);
                let _ = decompress_data(&blob);
                continue;
            }
            assert_eq!((c.decode)(stream).as_deref(), Ok(&src[..]), "{ctx}: decode");
            assert_eq!(
                decompress_data(&blob).as_deref(),
                Ok(&src[..]),
                "{ctx}: decompress_data"
            );
        }
    }
}

#[test]
#[ignore = "WP-7.2b: remove when the codecs are implemented"]
fn test_wp7_2b_compression_12_large_golden_vectors() {
    let lines = vector_lines();
    for line in &lines[SMALL_COUNT..] {
        let (seed, src) = large_payload(line);
        for c in &CODECS {
            let ctx = format!("seed {seed} {}", c.name);
            let blob = compress_data(c.comp_type, &src).expect("compress_data");
            assert_eq!(
                blob.len(),
                get_u32(line, c.len_key).expect("len") as usize,
                "{ctx}: blob length"
            );
            assert_eq!(
                fnv1a64(&blob),
                fnv_field(line, c.fnv_key),
                "{ctx}: blob digest"
            );
            assert_eq!(
                decompress_data(&blob).as_deref(),
                Ok(&src[..]),
                "{ctx}: decompress_data"
            );
        }
    }
}

#[test]
#[ignore = "WP-7.2b: remove when the codecs are implemented"]
fn test_wp7_2b_manager_header_rules() {
    // CompressionManager::getCompressionType / getUncompressedSize / compressData
    // (CompressionManager.cpp): magic table, the 8-byte minimum, and the unsupported types.
    let with_magic = |magic: &[u8; 4], len: i32| {
        let mut blob = magic.to_vec();
        blob.extend_from_slice(&len.to_le_bytes());
        blob
    };
    let table: [(&[u8; 4], CompressionType); 13] = [
        (b"NOX\0", CompressionType::NoxLzh),
        (b"ZL1\0", CompressionType::Zlib1),
        (b"ZL2\0", CompressionType::Zlib2),
        (b"ZL3\0", CompressionType::Zlib3),
        (b"ZL4\0", CompressionType::Zlib4),
        (b"ZL5\0", CompressionType::Zlib5),
        (b"ZL6\0", CompressionType::Zlib6),
        (b"ZL7\0", CompressionType::Zlib7),
        (b"ZL8\0", CompressionType::Zlib8),
        (b"ZL9\0", CompressionType::Zlib9),
        (b"EAB\0", CompressionType::BTree),
        (b"EAH\0", CompressionType::Huff),
        (b"EAR\0", CompressionType::RefPack),
    ];
    for (magic, ty) in table {
        let blob = with_magic(magic, 0x0102_0304);
        assert_eq!(get_compression_type(&blob), ty, "{magic:?}");
        assert!(is_data_compressed(&blob), "{magic:?}");
        assert_eq!(get_uncompressed_size(&blob), 0x0102_0304, "{magic:?}");
        assert_eq!(
            get_compression_type(&blob[..7]),
            CompressionType::None,
            "{magic:?} short"
        );
        assert_eq!(get_uncompressed_size(&blob[..7]), 7, "{magic:?} short");
    }
    for unknown in [b"EAX\0", b"ZL0\0", b"ear\0", b"EAR "] {
        let blob = with_magic(unknown, 99);
        assert_eq!(
            get_compression_type(&blob),
            CompressionType::None,
            "{unknown:?}"
        );
        assert!(!is_data_compressed(&blob), "{unknown:?}");
        assert_eq!(
            get_uncompressed_size(&blob),
            blob.len() as i32,
            "{unknown:?}"
        );
    }
    for ty in [
        CompressionType::None,
        CompressionType::NoxLzh,
        CompressionType::Zlib1,
        CompressionType::Zlib9,
    ] {
        assert_eq!(compress_data(ty, b"payload"), None, "{ty:?}");
    }
    assert_eq!(
        decompress_data(&with_magic(b"ZL5\0", 4)),
        Err(CodecError::Unsupported)
    );
    assert_eq!(
        decompress_data(&with_magic(b"NOX\0", 4)),
        Err(CodecError::Unsupported)
    );
    assert!(
        decompress_data(b"EAR\0").is_err(),
        "shorter than the header"
    );
}

#[test]
#[ignore = "WP-7.2b: remove when the codecs are implemented"]
fn test_wp7_2b_decoders_never_panic_on_truncated_or_corrupt_input() {
    // No C++ reference here: the C++ decoders read and write out of bounds on bad input.
    // The port must return (Ok or Err) for every truncation and single-byte corruption.
    let lines = vector_lines();
    for line in lines[..SMALL_COUNT].iter().step_by(50) {
        for c in &CODECS {
            let blob = hex_field(line, c.hex_key);
            if blob.len() <= COMPRESSION_HEADER_LEN {
                continue;
            }
            let stream = &blob[COMPRESSION_HEADER_LEN..];
            for cut in 0..stream.len() {
                let _ = (c.decode)(&stream[..cut]);
            }
            for pos in 0..stream.len().min(16) {
                let mut corrupt = stream.to_vec();
                corrupt[pos] ^= 0xff;
                let _ = (c.decode)(&corrupt);
            }
            for cut in 0..blob.len() {
                let _ = decompress_data(&blob[..cut]);
            }
        }
    }
}
